PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS catalog_accounts(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,role TEXT NOT NULL CHECK(role IN('owner','admin')),salt TEXT NOT NULL,digest TEXT NOT NULL,salon_name TEXT NOT NULL DEFAULT '',area TEXT NOT NULL DEFAULT '',latitude REAL,longitude REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS catalog_one_admin ON catalog_accounts(role) WHERE role='admin';
CREATE TABLE IF NOT EXISTS catalog_sessions(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES catalog_accounts(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_rate(key TEXT PRIMARY KEY,hits INTEGER NOT NULL DEFAULT 1,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS catalog_media(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),object_key TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS catalog_services(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),latest_revision TEXT,published_revision TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS catalog_revisions(id TEXT PRIMARY KEY,service_id TEXT NOT NULL REFERENCES catalog_services(id),owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN('hair','makeup','skin','nails')),price INTEGER NOT NULL CHECK(price>=0),minutes INTEGER NOT NULL CHECK(minutes>0),active INTEGER NOT NULL DEFAULT 1,media_id TEXT REFERENCES catalog_media(id),discount_price INTEGER,discount_start TEXT,discount_end TEXT,status TEXT NOT NULL CHECK(status IN('pending','approved','rejected')),reason TEXT NOT NULL DEFAULT '',reviewer TEXT REFERENCES catalog_accounts(id),reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK((discount_price IS NULL AND discount_start IS NULL AND discount_end IS NULL) OR(discount_price>0 AND discount_price<price AND discount_start IS NOT NULL AND discount_end>discount_start)));
CREATE TABLE IF NOT EXISTS catalog_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT NOT NULL,revision_id TEXT NOT NULL,event TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS catalog_review_queue ON catalog_revisions(status,created_at);
